PREFIX gene: <http://example.org/gene/>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX ex: <http://example.org/>
PREFIX ucscGb: <http://genome.ucsc.edu/>
PREFIX genebank: <http://ncbi.nlm.nih.gov/genebank/>
PREFIX ensembl: <http://www.ensembl.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX uniprot: <http://uniprot.org/uniprot/>
PREFIX uniprotRef: <http://uniprot.org/ref/>

# BRCA1 - the gene's own facts, in the default graph
gene:BRCA1
  gene:product gene:BRCA1-encodes-001 , gene:BRCA1-encodes-002 ;
  gene:chromosome gene:BRCA1-chr17 .

gene:BRCA1-encodes-001
  gene:encodes uniprot:P38398 ;
  prov:wasDerivedFrom uniprotRef:P38398 .

gene:BRCA1-encodes-002
  gene:encodes uniprot:P38398-2 ;
  prov:wasDerivedFrom uniprotRef:P38398-2 .

# each chromosome and reference record lives in the graph named for it
GRAPH gene:BRCA1-chr17 {
  gene:BRCA1-chr17
    gene:assembly [
      ucscGb:id "chr17:43044295-43125483" ;
      ex:publicationDate "2023-06-10T00:00:00Z"^^xsd:dateTime
    ] , [
      genebank:id "NC_000017.11" ;
      ex:publicationDate "2023-04-20T00:00:00Z"^^xsd:dateTime
    ] ;
    prov:wasDerivedFrom [ ensembl:geneId "ENSG00000012048" ] .
}

GRAPH uniprotRef:P38398 {
  uniprotRef:P38398 ex:id "P38398" ;
    ex:when "2024-01-15T09:30:00Z"^^xsd:dateTime .
}

GRAPH uniprotRef:P38398-2 {
  uniprotRef:P38398-2 ex:id "P38398-2" ;
    ex:when "2023-11-22T14:45:00Z"^^xsd:dateTime .
}

